"use client";

import * as PopoverPrimitive from "@radix-ui/react-popover";
import { forwardRef } from "react";
import type { ComponentPropsWithoutRef } from "react";
import { ESCAPE_LAYER_ATTRIBUTE, layerEscape } from "../lib/escape";
import styles from "./popover.module.css";

export const Popover = PopoverPrimitive.Root;
export const PopoverClose = PopoverPrimitive.Close;

/** The trigger anchors the panel, so it opts out of press-scale: a scaled rect measured on open would shift the panel as the trigger springs back. */
export const PopoverTrigger = forwardRef<
  HTMLButtonElement,
  ComponentPropsWithoutRef<typeof PopoverPrimitive.Trigger>
>(function PopoverTrigger({ className, ...props }, ref) {
  return <PopoverPrimitive.Trigger {...props} ref={ref} className={[styles.anchor, className].filter(Boolean).join(" ")}/>;
});

PopoverTrigger.displayName = "PopoverTrigger";

export const PopoverContent = forwardRef<
  HTMLDivElement,
  ComponentPropsWithoutRef<typeof PopoverPrimitive.Content>
>(function PopoverContent({ className, align = "start", sideOffset = 6, collisionPadding = 10, onEscapeKeyDown, ...props }, ref) {
  return <PopoverPrimitive.Portal>
    <PopoverPrimitive.Content
      {...props}
      {...{ [ESCAPE_LAYER_ATTRIBUTE]: "" }}
      // Escape inside belongs to an open list, calendar or question first (lib/escape.ts).
      onEscapeKeyDown={layerEscape(onEscapeKeyDown)}
      ref={ref}
      align={align}
      sideOffset={sideOffset}
      collisionPadding={collisionPadding}
      className={[styles.content, className].filter(Boolean).join(" ")}
    />
  </PopoverPrimitive.Portal>;
});

PopoverContent.displayName = "PopoverContent";

/* Press feedback on the anchor stays in color. Radix measures the trigger when the panel opens, so a scaled trigger would move the panel. */
.anchor:active:not(:disabled) { transform: none; }
.content {
  --popover-x: 0px;
  --popover-y: -5px;
  z-index: 80;
  min-width: 12rem;
  max-width: min(22rem, calc(100vw - 20px));
  padding: var(--space-inset);
  border: 1px solid var(--border);
  border-radius: var(--radius-container);
  background: var(--surface-raised);
  color: var(--foreground);
  box-shadow: var(--shadow-floating);
  transform-origin: var(--radix-popover-content-transform-origin);
  transition: opacity var(--duration-fast) var(--ease-enter), transform var(--duration-spring) var(--ease-spring);
}
/* The panel starts a few pixels toward its trigger and settles on a spring; it leaves faster than it arrives.
   Transitions instead of keyframes, so a close that interrupts the open, or a reopen during the close, reverses from where the panel is. */
.content[data-side="top"] { --popover-y: 5px; }
.content[data-side="left"] { --popover-x: 5px; --popover-y: 0px; }
.content[data-side="right"] { --popover-x: -5px; --popover-y: 0px; }
@starting-style {
  .content[data-state="open"] { opacity: 0; transform: translate(var(--popover-x), var(--popover-y)) scale(.97); }
}
/* Radix unmounts when the exit animation ends, so a no-op keyframe times the exit while the transition does the visual work. */
.content[data-state="closed"] { opacity: 0; transform: translate(calc(var(--popover-x) * .5), calc(var(--popover-y) * .5)) scale(.98); transition: opacity var(--duration-fast) var(--ease-standard), transform var(--duration-fast) var(--ease-standard); animation: popover-exit var(--duration-fast) linear both; pointer-events: none; }
.content:focus { outline: none; }
@keyframes popover-exit { to { --popover-exit: 1; } }
@media (prefers-reduced-motion: reduce) {
  .content, .content[data-state="closed"] { transform: none; transition: opacity var(--duration-instant) var(--ease-standard); }
}

/**
 * Escape inside a layer (Dialog, Drawer, BottomSheet, Popover) belongs to the control that has focus when that control
 * has something of its own to close: an open Combobox list, an open DatePicker calendar, an InlineEdit being edited, a
 * ConfirmMorph asking its question. Only the next Escape closes the layer.
 *
 * Radix closes its layers from a capture listener on the document, before the control's own key handler runs, so every
 * Silicon UI layer passes its `onEscapeKeyDown` through `layerEscape` (and marks its own panel with `data-escape-layer`, where
 * the search for an inner popup stops). Pages need nothing for this; their own `onEscapeKeyDown` still runs first and
 * can keep the layer open for reasons of its own with `event.preventDefault()`.
 */

/** Marks a layer's own panel (so it is never mistaken for a popup of a control inside it). */
export const ESCAPE_LAYER_ATTRIBUTE = "data-escape-layer";

/** Controls that close something of their own on Escape while focus is in them. */
const OWN_ESCAPE = [
  // Combobox with its list open (focus stays in its input).
  '[role="combobox"][aria-expanded="true"]',
  // DatePicker's trigger (or any popup button) while its panel is open.
  '[aria-haspopup="dialog"][aria-expanded="true"]',
  '[aria-haspopup="listbox"][aria-expanded="true"]',
  // InlineEdit while editing: Escape puts the saved text back.
  "[data-editing]",
].join(", ");

/** ConfirmMorph asking its question or showing a result (Escape returns it to rest). */
const MORPH_STATES = '[data-state="confirming"], [data-state="done"], [data-state="error"]';

/** True when Escape at `target` is handled by a control inside the layer, which closes its own part first. */
export function escapeBelongsInside(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  if (target.closest(OWN_ESCAPE)) return true;
  // A ConfirmMorph's root (focused while it works or shows a result) or one of its faces. A HoldToConfirm button also
  // says data-state="done", but it has no faces and no Escape of its own.
  const morph = target.closest(MORPH_STATES);
  if (morph?.querySelector("[data-face]")) return true;
  // A popup of a control (DatePicker's calendar is a dialog inside the layer); the layer's own panel is not one.
  const dialog = target.closest('[role="dialog"]');
  return !!dialog && !dialog.hasAttribute(ESCAPE_LAYER_ATTRIBUTE);
}

/**
 * The `onEscapeKeyDown` a Silicon UI layer gives Radix: the page's own handler first, then the layer stays open when the
 * Escape belongs to a control inside it.
 */
export function layerEscape<E extends KeyboardEvent>(own?: (event: E) => void): (event: E) => void {
  return event => {
    own?.(event);
    if (!event.defaultPrevented && escapeBelongsInside(event.target)) event.preventDefault();
  };
}
